html:
{% set template = get_template_context(doc.template) %}
{% set rows = expand_print_rows(doc) %}
{% set cols = template.column_count or 1 %}
<style>
  @page {
    size: {{ (template.label_width_mm * cols) + (template.column_gap_mm * (cols - 1)) }}mm {{ template.label_height_mm + template.row_gap_mm }}mm;
    margin: 0;
  }
  * { box-sizing: border-box; }
  body { margin: 0; padding: 0; font-family: {{ template.font_family or "Arial, Helvetica, sans-serif" }}; }
  .page-row { page-break-after: always; }
  .page-row:last-child { page-break-after: auto; }
  .cols {
    display: grid;
    grid-template-columns: repeat({{ cols }}, {{ template.label_width_mm }}mm);
    column-gap: {{ template.column_gap_mm }}mm;
  }
  .row-gap { height: {{ template.row_gap_mm }}mm; }
  .aim-barcode-label {
    width: {{ template.label_width_mm }}mm;
    height: {{ template.label_height_mm }}mm;
    padding: 1mm 2mm;
    overflow: hidden;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    text-align: center;
  }
  .company-row {
    font-size: {{ template.item_name_font_size }}pt;
    font-weight: bold;
    line-height: 1.15;
  }
  .barcode-img { width: 90%; height: {{ template.barcode_height_mm }}mm; object-fit: contain; }
  .barcode-text {
    font-size: {{ template.item_code_font_size }}pt;
    font-weight: bold;
    letter-spacing: 1px;
    line-height: 1.2;
  }
  .item-name {
    font-size: {{ template.item_code_font_size }}pt;
    font-weight: bold;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
    max-width: 100%;
    line-height: 1.2;
  }
  .price-row {
    font-size: {{ template.price_font_size }}pt;
    font-weight: bold;
    line-height: 1.3;
    margin-top: 1mm;
  }
  .meta-row {
    font-size: 6.5pt;
    display: flex;
    justify-content: center;
    gap: 3mm;
    line-height: 1.2;
  }
  {{ template.custom_css or "" }}
</style>
<div class="label-sheet">
{% for row_group in rows|batch(cols) %}
  <div class="page-row">
    <div class="cols">
      {% for row in row_group %}
        <div class="aim-barcode-label">
          {% if template.show_company and doc.company %}<div class="company-row">{{ doc.company }}</div>{% endif %}
          {% if row.barcode %}
            <img class="barcode-img" src="{{ get_barcode_data_uri(row.barcode, template.barcode_type, template.barcode_height_mm) }}" alt="barcode">
            {% if template.show_barcode_text %}<div class="barcode-text">{{ row.barcode }}</div>{% endif %}
          {% else %}
            <div class="barcode-text">NO BARCODE</div>
          {% endif %}
          {% if template.show_item_name %}<div class="item-name">{{ row.item_name }}</div>{% endif %}
          {% if template.show_price or template.show_mrp %}
          <div class="price-row">
            {% if template.show_price %}Rs. {{ format_price(row.price) }}{% endif %}
            {% if template.show_mrp %}&nbsp;&nbsp;MRP {{ format_price(row.mrp) }}{% endif %}
          </div>
          {% endif %}
          {% if template.show_item_code or template.show_uom %}
          <div class="meta-row">
            {% if template.show_item_code %}<span>{{ row.item_code }}</span>{% endif %}
            {% if template.show_uom and row.uom %}<span>{{ row.uom }}</span>{% endif %}
          </div>
          {% endif %}
          {% if template.show_batch_no and row.batch_no %}<div class="meta-row"><span>Batch: {{ row.batch_no }}</span></div>{% endif %}
          {% if template.show_mfg_date and row.final_mfg_date %}<div class="meta-row"><span>MFG: {{ row.final_mfg_date }}</span></div>{% endif %}
          {% if template.show_expiry_date and row.final_expiry_date %}<div class="meta-row"><span>EXP: {{ row.final_expiry_date }}</span></div>{% endif %}
          {% if template.show_shelf_location and row.shelf_location %}<div class="meta-row"><span>{{ row.shelf_location }}</span></div>{% endif %}
        </div>
      {% endfor %}
    </div>
    <div class="row-gap"></div>
  </div>
{% endfor %}
</div>
